<script lang="ts">
  import { onMount } from 'svelte';
  import { VoxelDocument, type Cell, type Vec3 } from '../../../../voxel-core/index';
  import * as THREE from 'three';
  import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

  let host: HTMLDivElement;
  let fileInput: HTMLInputElement;
  let doc = new VoxelDocument();
  let objects = doc.snapshot().objects;
  let selected = '';
  let selectedCell: Cell | null = null;
  let mode: 'select' | 'draw' = 'select';
  let step = 0.2, height = 2, name = '新物体', semantic = 'object';
  let position: Vec3 = [0, 0, 0];
  let message = '选择“框选创建”，在地面拖出底面。';
  let draft: { x: number; z: number; y: number; a: number; b: number } | null = null;
  let redraw = () => {};
  let resetView = () => {};
  const storageKey = 'angrid-experiment13-voxel-v1';
  const colors = [0x9d785e, 0x719485, 0xd5a666, 0x798eaa, 0xb47b6d, 0x9c91ae];
  $: current = objects.find((o) => o.id === selected);
  function sync() { objects = doc.snapshot().objects; if (!objects.some(o => o.id === selected)) { selected = ''; selectedCell = null; } if (selected) position = [...(objects.find(o => o.id === selected)!.origin)] as Vec3; redraw(); }
  function perform(action: () => unknown, text: string) { try { action(); sync(); message = text; } catch (e) { message = e instanceof Error ? e.message : String(e); } }
  function choose(id: string, cell: Cell | null = null) { selected = id; selectedCell = cell; const o = doc.getObject(id); if (o) position = [...o.origin]; sync(); }
  function create() { if (!draft) { message = '先在画布上拖出底面。'; return; } if (!(step > 0) || !Number.isInteger(height) || height < 1) { message = '格子尺寸与高度必须大于零。'; return; } const d = draft; perform(() => { const id = crypto.randomUUID(); doc.createBox({id, name: name.trim() || '新物体', semantic, baseStep: step, origin: [d.x, d.y, d.z], dimensions: [d.a, height, d.b]}); selected = id; selectedCell = null; draft = null; }, '已创建可编辑体素物体。'); }
  function save() { perform(() => localStorage.setItem(storageKey, doc.toJSON()), '已保存到此浏览器。'); }
  function load() { perform(() => { const data = localStorage.getItem(storageKey); if (!data) throw new Error('此浏览器还没有保存的体素场景。'); doc = VoxelDocument.fromJSON(data); selected = ''; selectedCell = null; draft = null; }, '已载入本地场景。'); }
  function exportFile() { const blob = new Blob([doc.toJSON()], {type: 'application/json'}); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'voxel-scene.json'; a.click(); URL.revokeObjectURL(url); message = '已导出体素场景 JSON。'; }
  async function importFile(event: Event) { const input = event.currentTarget as HTMLInputElement; try { const f = input.files?.[0]; if (!f) return; const next = VoxelDocument.fromJSON(await f.text()); doc = next; selected = ''; selectedCell = null; draft = null; sync(); message = '已导入体素场景。'; } catch (e) { message = `导入失败：${e instanceof Error ? e.message : String(e)}`; } finally { input.value = ''; } }
  onMount(() => {
    const scene = new THREE.Scene(); scene.background = new THREE.Color(0xf1f0ea);
    const camera = new THREE.PerspectiveCamera(45, 1, .01, 200); camera.position.set(5, 5, 6);
    const renderer = new THREE.WebGLRenderer({antialias:true}); renderer.setPixelRatio(Math.min(devicePixelRatio, 2)); renderer.shadowMap.enabled = true; host.appendChild(renderer.domElement);
    const controls = new OrbitControls(camera, renderer.domElement); controls.target.set(0, .5, 0); controls.enableDamping = true;
    scene.add(new THREE.HemisphereLight(0xffffff, 0xb5aca0, 2)); const light = new THREE.DirectionalLight(0xffffff, 2); light.position.set(4,8,5); scene.add(light);
    const grid = new THREE.GridHelper(20, 100, 0xaaa99e, 0xd7d6ce); scene.add(grid);
    const root = new THREE.Group(); scene.add(root); const preview = new THREE.Group(); scene.add(preview);
    const ray = new THREE.Raycaster(); const mouse = new THREE.Vector2(); const matrix = new THREE.Matrix4();
    const box = new THREE.BoxGeometry(1,1,1); let disposed = false; let pointerStart: {x:number;z:number;y:number} | null = null; let pointerDown: {x:number;y:number} | null = null;
    function clear(group: THREE.Group) { for (const item of [...group.children]) { group.remove(item); if (item instanceof THREE.Mesh) { if (item.geometry !== box) item.geometry.dispose(); const materials = Array.isArray(item.material) ? item.material : [item.material]; materials.forEach(m => m.dispose()); } } }
    function renderPreview() { clear(preview); if (!draft) return; const geometry = new THREE.BoxGeometry(draft.a*step, height*step, draft.b*step); const mesh = new THREE.Mesh(geometry, new THREE.MeshBasicMaterial({color:0xd98c4a, transparent:true, opacity:.3, depthWrite:false})); mesh.position.set(draft.x+draft.a*step/2, draft.y+height*step/2, draft.z+draft.b*step/2); preview.add(mesh); }
    redraw = () => { clear(root); objects.forEach((o, i) => { if (!o.cells.length) return; const material = new THREE.MeshStandardMaterial({color: selected === o.id ? 0xd69a50 : colors[i%colors.length], roughness:.8}); const mesh = new THREE.InstancedMesh(box, material, o.cells.length); mesh.userData.objectId = o.id; mesh.userData.cells = o.cells; o.cells.forEach((c, n) => { const s = o.baseStep / 2**c.level; const center = doc.cellWorldCenter(o.id, c); matrix.makeScale(s*.985,s*.985,s*.985); matrix.setPosition(...center); mesh.setMatrixAt(n,matrix); if (selected === o.id && selectedCell && c.level === selectedCell.level && c.x === selectedCell.x && c.y === selectedCell.y && c.z === selectedCell.z) mesh.setColorAt(n,new THREE.Color(0xf7db76)); }); mesh.instanceMatrix.needsUpdate = true; root.add(mesh); }); renderPreview(); };
    function raycast(event: PointerEvent) { const r = renderer.domElement.getBoundingClientRect(); mouse.set((event.clientX-r.left)/r.width*2-1, -(event.clientY-r.top)/r.height*2+1); ray.setFromCamera(mouse,camera); }
    function surface(event: PointerEvent, fixedY?: number) { raycast(event); let y = fixedY ?? 0; if (fixedY === undefined) { const hits = ray.intersectObjects(root.children); const top = hits.find(h => h.face && h.face.normal.y > .9); if (top && top.instanceId !== undefined) { const o = doc.getObject(top.object.userData.objectId)!; const c = top.object.userData.cells[top.instanceId] as Cell; y = doc.cellWorldCenter(o.id, c)[1] + o.baseStep / 2**c.level / 2; } } const p = new THREE.Vector3(); if (!ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),-y),p)) return null; return { x: Math.floor(p.x/step)*step, z: Math.floor(p.z/step)*step, y }; }
    function down(e: PointerEvent) { if (e.button !== 0) return; pointerDown = {x:e.clientX,y:e.clientY}; if (mode === 'draw') { if (!(step > 0)) return; pointerStart = surface(e); if (!pointerStart) return; controls.enabled = false; renderer.domElement.setPointerCapture(e.pointerId); draft = { ...pointerStart, a:1,b:1 }; renderPreview(); } }
    function move(e: PointerEvent) { if (!pointerStart || mode !== 'draw') return; const p = surface(e,pointerStart.y); if (!p) return; const x = Math.min(p.x,pointerStart.x), z = Math.min(p.z,pointerStart.z); draft = {x,z,y:pointerStart.y,a:Math.round(Math.abs(p.x-pointerStart.x)/step)+1,b:Math.round(Math.abs(p.z-pointerStart.z)/step)+1}; renderPreview(); }
    function up(e: PointerEvent) { if (mode === 'draw' && pointerStart) { pointerStart = null; controls.enabled = true; message = '底面已选定，设置高度后确认创建。'; return; } if (mode !== 'select' || e.button !== 0) return; if (pointerDown && Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)>4) { pointerDown = null; return; } pointerDown = null; raycast(e); const hit = ray.intersectObjects(root.children)[0]; if (hit && hit.instanceId !== undefined) choose(hit.object.userData.objectId, hit.object.userData.cells[hit.instanceId]); else { selected = ''; selectedCell = null; sync(); } }
    renderer.domElement.addEventListener('pointerdown',down); renderer.domElement.addEventListener('pointermove',move); renderer.domElement.addEventListener('pointerup',up);
    const resize = new ResizeObserver(() => { const w=host.clientWidth,h=host.clientHeight; if (!w || !h) return; camera.aspect=w/h; camera.updateProjectionMatrix(); renderer.setSize(w,h); }); resize.observe(host);
    resetView = () => { camera.position.set(5,5,6); controls.target.set(0,.5,0); controls.update(); };
    function animate() { if (disposed) return; controls.update(); renderer.render(scene,camera); requestAnimationFrame(animate); } redraw(); animate();
    return () => { disposed=true; resize.disconnect(); controls.dispose(); clear(root); clear(preview); box.dispose(); renderer.dispose(); renderer.domElement.remove(); };
  });
</script>

<svelte:head><title>体素工作台 · 实验 7</title><meta name="description" content="本地体素编辑实验" /></svelte:head>
<div class="app">
  <header><div><span class="mark">A</span><strong>空间体素工作台</strong><small>实验 7 / 本地原型</small></div><nav><a href="/editor">打开平面图编辑器 ↗</a><button on:click={save}>保存到浏览器</button><button on:click={load}>读取</button><button on:click={exportFile}>导出 JSON</button><button on:click={() => fileInput.click()}>导入</button><input bind:this={fileInput} type="file" accept="application/json,.json" on:change={importFile} hidden /></nav></header>
  <div class="workspace"><aside class="objects"><div class="heading"><div><span class="eyebrow">SCENE</span><h2>场景物体</h2></div><span class="count">{objects.length}</span></div><p>每件物体拥有独立格子和身份。</p>{#each objects as object}<button class:active={selected === object.id} class="object" on:click={() => choose(object.id)}><span class="cube">▦</span><span><b>{object.name}</b><small>{object.semantic} · {object.cells.length} 格</small></span><span>›</span></button>{:else}<div class="empty">还没有物体<br /><small>在画布中框选底面开始创建</small></div>{/each}</aside>
  <main><div class="toolbar"><div class="modes"><button class:chosen={mode === 'select'} on:click={() => mode='select'}>↖ 选择</button><button class:chosen={mode === 'draw'} on:click={() => mode='draw'}>▧ 框选创建</button></div><span class="hint">{mode === 'draw' ? '左键拖动底面 · 右键旋转视角' : '点击格子选择 · 拖动旋转视角'}</span><button on:click={resetView}>复位视角</button><button on:click={() => perform(() => doc.undo(),'已撤销。')}>撤销</button><button on:click={() => perform(() => doc.redo(),'已重做。')}>重做</button></div><div class="canvas" bind:this={host}></div><div class="status"><span class="dot"></span>{message}<span class="spacer"></span>单位：米 · Y 轴向上</div></main>
  <aside class="properties"><div class="heading"><div><span class="eyebrow">WORKSPACE</span><h2>{mode === 'draw' ? '创建物体' : '属性与编辑'}</h2></div></div>{#if mode === 'draw'}<p>框选底面，再设置高度。也可从已有体素的顶面开始。</p><label>格子边长 <span>米</span><input type="number" min="0.01" step="0.01" bind:value={step} on:change={() => {draft=null; redraw();}} /></label><label>高度 <span>格</span><input type="number" min="1" max="100" step="1" bind:value={height} on:input={redraw} /></label><label>物体名称<input bind:value={name} /></label><label>语义标签<input bind:value={semantic} placeholder="例如 desk、cabinet" /></label><div class="summary">{#if draft}<strong>{draft.a} × {height} × {draft.b} 格</strong><small>底面高度 {draft.y.toFixed(2)} m · 预计 {draft.a*height*draft.b} 格</small>{:else}<strong>等待框选</strong><small>在画布中按住左键拖动</small>{/if}</div><button class="primary" on:click={create} disabled={!draft}>确认创建</button><button class="wide" on:click={() => {draft=null; redraw();}}>取消框选</button>{:else if current}<p>选择的格子属于此物体；不同物体的格子互不合并。</p><label>名称<input value={current.name} on:change={(e) => perform(() => doc.rename(current!.id, e.currentTarget.value),'名称已更新。')} /></label><div class="summary"><strong>{current.cells.length} 个格子</strong><small>语义 {current.semantic} · 体积 {doc.volume(current.id).toFixed(4)} m³</small></div><div class="position-label">物体位置 <span>米</span></div><div class="coords">{#each [0,1,2] as axis}<label>{['X','Y','Z'][axis]}<input type="number" step="0.1" bind:value={position[axis]} /></label>{/each}</div><button class="wide" on:click={() => perform(() => doc.move(current!.id, position),'物体位置已更新。')}>应用位置</button><button class="wide" on:click={() => perform(() => doc.rotate(current!.id, ((current!.quarterTurns+1)%4) as 0|1|2|3),'已旋转 90°。')}>旋转 90°</button><div class="divider"></div><div class="summary"><strong>{selectedCell ? '已选择一个格子' : '未选择格子'}</strong><small>{selectedCell ? `层级 ${selectedCell.level} · ${selectedCell.x}, ${selectedCell.y}, ${selectedCell.z}` : '点击画布上的格子进行编辑'}</small></div><button class="wide" disabled={!selectedCell} on:click={() => perform(() => {doc.refine(current!.id,[selectedCell!]); selectedCell=null;},'已将选中格拆成 8 格。')}>细分选中格 × 8</button><button class="wide" disabled={!selectedCell} on:click={() => perform(() => {doc.removeCell(current!.id,selectedCell!); selectedCell=null;},'已删除选中格。')}>删除选中格</button><button class="danger wide" on:click={() => perform(() => doc.deleteObject(current!.id),'已删除物体，可撤销。')}>删除物体</button>{:else}<div class="empty">选择画布中的物体<br /><small>查看属性、移动或编辑单格</small></div>{/if}</aside></div>
</div>
<style>
  :global(body){margin:0;font-family:Inter,-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;color:#30382f} :global(*){box-sizing:border-box} button,input{font:inherit} button{cursor:pointer} button:disabled{opacity:.42;cursor:not-allowed}.app{height:100dvh;min-height:560px;background:#f5f5ef;display:flex;flex-direction:column} header{height:66px;flex:none;background:#fff;border-bottom:1px solid #e5e7dd;display:flex;align-items:center;justify-content:space-between;padding:0 22px;gap:12px}header>div,nav{display:flex;align-items:center;gap:10px}header strong{font-size:15px}header small{color:#8a9184;font-size:11px}.mark{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;background:#365f4d;color:white;font-weight:800}nav a{color:#60766a;font-size:12px;text-decoration:none;margin-right:10px}button{border:1px solid #e0e4d9;background:#fff;border-radius:7px;color:#526154;padding:8px 10px;font-size:12px}button:hover:not(:disabled){border-color:#89a391;background:#f5f8f3}.workspace{display:grid;grid-template-columns:224px minmax(0,1fr) 270px;flex:1;min-height:0}.objects,.properties{background:#fff;padding:22px 16px;overflow:auto}.objects{border-right:1px solid #e5e7dd}.properties{border-left:1px solid #e5e7dd}.heading{display:flex;align-items:center;justify-content:space-between}.eyebrow{font-size:10px;letter-spacing:.14em;color:#9aa497;font-weight:700}h2{font-size:16px;margin:5px 0 0}.count{font-size:11px;color:#738477;background:#f0f3ed;padding:4px 8px;border-radius:10px}p{font-size:12px;color:#899387;line-height:1.6;margin:14px 0 20px}.object{display:flex;width:100%;align-items:center;gap:10px;text-align:left;border:1px solid transparent;margin:4px 0;padding:10px}.object.active{background:#edf4ee;border-color:#cbded0;color:#315b46}.object span:nth-child(2){flex:1}.object b,.object small{display:block}.object small{font-size:10px;color:#94a094;margin-top:4px}.cube{font-size:20px;color:#76917e}.empty{text-align:center;border:1px dashed #dce3d9;border-radius:10px;padding:25px 6px;color:#859184;font-size:12px;line-height:2}.empty small{color:#b0b9ad}main{min-width:0;min-height:0;display:flex;flex-direction:column}.toolbar{display:flex;align-items:center;gap:7px;background:#fafbf8;border-bottom:1px solid #e3e6de;padding:9px 12px}.modes{display:flex;gap:4px}.modes .chosen{background:#355e4a;color:white;border-color:#355e4a}.hint{color:#96a095;font-size:11px;flex:1}.canvas{flex:1;min-height:0;position:relative}.canvas :global(canvas){display:block;width:100%;height:100%;touch-action:none}.status{display:flex;align-items:center;gap:8px;background:#fff;border-top:1px solid #e5e7dd;padding:9px 14px;color:#7b8a7d;font-size:11px}.dot{width:6px;height:6px;border-radius:50%;background:#7aac87}.spacer{flex:1}label{display:block;color:#6d7a6d;font-size:11px;margin:14px 0 5px;font-weight:600}label span{float:right;color:#adb7aa}input{display:block;width:100%;border:1px solid #dfe5dc;border-radius:7px;padding:9px;margin-top:6px;background:#fbfcfa;color:#334235;outline:none}input:focus{border-color:#87ab91}.summary{background:#f5f7f2;border-radius:8px;padding:12px;margin:14px 0;color:#455c4a}.summary strong,.summary small{display:block}.summary strong{font-size:12px}.summary small{font-size:11px;color:#98a597;margin-top:6px}.primary,.wide{width:100%;margin:4px 0}.primary{background:#365f4d;color:white;border-color:#365f4d}.primary:hover:not(:disabled){background:#244b39;color:#fff}.danger{color:#ad5f54}.position-label{color:#6d7a6d;font-size:11px;margin:14px 0 5px;font-weight:600}.position-label span{float:right;color:#adb7aa}.coords{display:flex;gap:6px}.coords label{flex:1;min-width:0;margin:0}.coords input{padding:7px 4px}.divider{border-top:1px solid #e8ece5;margin:18px 0}@media(max-width:850px){.workspace{grid-template-columns:150px minmax(0,1fr) 220px}.hint,header small,nav a{display:none}.objects,.properties{padding:14px 10px}header{padding:0 10px}}@media(max-width:600px){.workspace{grid-template-columns:minmax(0,1fr) 200px}.objects{display:none}header nav button:nth-child(2),header nav button:nth-child(3){display:none}.toolbar{flex-wrap:wrap}}
</style>
